    private static ArmyStrengths.FamilyValue<?> normalize(ArmyStrengthsFamilies.Key key,JsonNode value){return registry.normalize(key,value.isNull()?new NullValue<>():new Present<>(new RawJson(bytes(value))),context);}
    private static void sameDomain(JsonNode expected,JsonNode actual){assertDoesNotThrow(()->BattleControlExtensionCodec.same(expected,actual));}
    @Test void allTenActualInstalledTypedFamiliesMatchOriginalAndNativeRoundTrip()throws Exception{
        assertTrue(registry.coverage().installed().containsAll(KEYS));for(var key:KEYS){JsonNode input=fixture(key);var actual=normalize(key,input);assertInstanceOf(Present.class,actual.value());JsonNode nativeJson=ArmyStrengthsCodec.parseValue(actual.normalizedJson());sameDomain(ArmyStrengthsMonthlyOriginal.normalize(key,input,List.of(7)),nativeJson);var round=normalize(key,nativeJson);assertEquals(actual.value(),round.value(),key.name());sameDomain(nativeJson,ArmyStrengthsCodec.parseValue(round.normalizedJson()));}
    }
    @Test void everyFamilyRejectsUnknownMissingAndIncorrectTopLevelTokens(){
        for(var key:KEYS){ObjectNode unknown=fixture(key);unknown.put("invented_field",true);assertThrows(IllegalArgumentException.class,()->normalize(key,unknown),key.name());ObjectNode missing=fixture(key);missing.remove(missing.fieldNames().next());assertThrows(IllegalArgumentException.class,()->normalize(key,missing),key.name());assertThrows(IllegalArgumentException.class,()->normalize(key,empty().arrayNode()),key.name());}
    }
    @Test void nullAndMissingAreExplicitAndNotRecoveredFromOtherInputs(){
        for(var key:KEYS){assertInstanceOf(NullValue.class,normalize(key,empty().nullNode()).value());var missing=registry.normalize(key,new Missing<>(),context);assertTrue(key.defaultNullWhenMissing()?missing.value() instanceof NullValue<?>:missing.value() instanceof Missing<?>);}
    }
    @Test void publicV2WideValuesAreDecimalStringsWhileNativeDomainRemainsNumeric(){
        var caller=normalize(ArmyStrengthsFamilies.Key.MONTHLY_CALLER_EFFECT_INPUTS_V1,fixture(ArmyStrengthsFamilies.Key.MONTHLY_CALLER_EFFECT_INPUTS_V1));assertEquals("9007199254740993",ArmyStrengthsCodec.parseValue(caller.publicV2Json()).path("current_date_storage_raw64").textValue());assertTrue(ArmyStrengthsCodec.parseValue(caller.normalizedJson()).path("current_date_storage_raw64").isIntegralNumber());
        var maa=normalize(ArmyStrengthsFamilies.Key.NATIVE_MAA_RECRUITMENT_INPUTS_V1,maa());assertEquals(Long.toString(Long.MIN_VALUE),ArmyStrengthsCodec.parseValue(maa.publicV2Json()).path("types_in_native_order").get(0).path("regular_personal_quote").path("resources_raw").get(0).textValue());
        var writer=normalize(ArmyStrengthsFamilies.Key.ACTUAL_LOSS_WRITER_OBSERVATIONS_V1,writer());assertEquals(Long.toString(Long.MIN_VALUE),ArmyStrengthsCodec.parseValue(writer.publicV2Json()).path("events").get(0).path("request_raw").textValue());
        var casualty=normalize(ArmyStrengthsFamilies.Key.BATTLE_CASUALTY_OBSERVATIONS_V1,casualty());assertEquals("18446744073709551615",ArmyStrengthsCodec.parseValue(casualty.publicV2Json()).path("events").get(0).path("entry_identity").textValue());
    }
